SET lock_timeout = '3s';

-- v2.2987 — One company, Phase 5: the adoption / sharing grant tables become views.
--
-- docs/ONE_COMPANY_PLAN.md Phase 5. After Phases 1–4 nothing decides ACCESS by
-- master_assistants / master_shares any more — but 45 SECURITY DEFINER functions still read
-- them by name (SQL-language bodies resolve at call time), 84 policies still carry the old
-- adoption branches inside their `is_office_staff() OR (…)` wrapper, and sync_company_access_grants()
-- (v2.921) has been filling the tables so all of that keeps passing. Dropping or renaming the
-- tables under those readers would break every one of those gates.
--
-- So the tables are retired by RULE instead of by drop:
--   1) sync_company_access_grants() stops filling them (primaries / superintendents unchanged —
--      those roles stay walled and their tables stay real).
--   2) The tables are renamed retired_master_assistants / retired_master_shares (rollback = the
--      reverse rename; their rows stay put; their own RLS policies travel with them).
--   3) Same-named VIEWS take their place, computed from public.users:
--        master_assistants = every live dev/master  ×  every live assistant / controller / estimator
--        master_shares     = every live dev/master  ×  every other live dev/master
--      That is exactly what the sync produced (owners × assistant/controller, owners × owners)
--      plus the two hand-made estimator adoptions found on 2026-09-07 (Malachi → Wendi, William),
--      which the rule now grants for every owner — meaningless after the Phase 4 backfill filed
--      every row under the one company owner. The one hand-made share outside the rule
--      (a dev → a primary) is dropped: the dev holds no rows any more.
--      Every function that reads the tables keeps working, with no data to keep in sync.
--      Plain views (owner = postgres, no security_invoker) so a policy or function reading them
--      sees the same pairs whoever the caller is; SELECT for authenticated + service_role only.
--   4) The 84 policies that name the tables are DROP + CREATEd byte-identical (generated by
--      scripts/one-company-policy-sweep.py --rebind) so their parsed expressions bind to the
--      views — a policy expression holds relation OIDs, so without this they would keep reading
--      the retired tables.
--
-- Nothing changes for any role: office roles pass the wrapper outright; primaries, superintendents,
-- estimators, helpers and subs get identical answers from the views. The retired tables are dropped
-- in a later chore after a quiet week (Phase 5c). Idempotent: reruns rename nothing and re-create
-- the same views and policies.

-- 1) The sync stops writing the retired pair ----------------------------------------------

CREATE OR REPLACE FUNCTION public.sync_company_access_grants()
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH owners AS (
    SELECT id FROM public.users
    WHERE archived_at IS NULL AND role IN ('dev', 'master_technician')
  )
  INSERT INTO public.master_primaries (master_id, primary_id)
  SELECT o.id, u.id
  FROM owners o
  CROSS JOIN public.users u
  WHERE u.archived_at IS NULL AND u.role = 'primary'
  ON CONFLICT DO NOTHING;
  WITH owners AS (
    SELECT id FROM public.users
    WHERE archived_at IS NULL AND role IN ('dev', 'master_technician')
  )
  INSERT INTO public.master_superintendents (master_id, superintendent_id)
  SELECT o.id, u.id
  FROM owners o
  CROSS JOIN public.users u
  WHERE u.archived_at IS NULL AND u.role = 'superintendent'
  ON CONFLICT DO NOTHING;
$$;

COMMENT ON FUNCTION public.sync_company_access_grants() IS
  'Company-wide access (v2.921): fills master_primaries / master_superintendents with every eligible live pair so primary and superintendent scoping is automatic. Since v2.2987 (one company, Phase 5) master_assistants / master_shares are views computed from users and are no longer written. Additive + idempotent; called by trigger on users role/archived_at changes.';

-- 2) Rename the tables (once) ---------------------------------------------------------------

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
             WHERE n.nspname = 'public' AND c.relname = 'master_assistants' AND c.relkind = 'r') THEN
    ALTER TABLE public.master_assistants RENAME TO retired_master_assistants;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
             WHERE n.nspname = 'public' AND c.relname = 'master_shares' AND c.relkind = 'r') THEN
    ALTER TABLE public.master_shares RENAME TO retired_master_shares;
  END IF;
END $$;

COMMENT ON TABLE public.retired_master_assistants IS
  'RETIRED 2026-09-07 (v2.2987, one company Phase 5): the old per-master adoption rows, kept for rollback only. Nothing reads or writes this; public.master_assistants is now a view. Drop after a quiet week (Phase 5c).';
COMMENT ON TABLE public.retired_master_shares IS
  'RETIRED 2026-09-07 (v2.2987, one company Phase 5): the old master↔master sharing rows, kept for rollback only. Nothing reads or writes this; public.master_shares is now a view. Drop after a quiet week (Phase 5c).';

-- 3) The views ------------------------------------------------------------------------------

CREATE OR REPLACE VIEW public.master_assistants AS
  SELECT o.id AS master_id,
         u.id AS assistant_id,
         u.created_at
  FROM public.users o
  CROSS JOIN public.users u
  WHERE o.archived_at IS NULL
    AND o.role IN ('dev', 'master_technician')
    AND u.archived_at IS NULL
    AND u.role IN ('assistant', 'controller', 'estimator')
    AND u.id <> o.id;

CREATE OR REPLACE VIEW public.master_shares AS
  SELECT a.id AS sharing_master_id,
         b.id AS viewing_master_id,
         b.created_at
  FROM public.users a
  CROSS JOIN public.users b
  WHERE a.archived_at IS NULL
    AND b.archived_at IS NULL
    AND a.role IN ('dev', 'master_technician')
    AND b.role IN ('dev', 'master_technician')
    AND a.id <> b.id;

ALTER VIEW public.master_assistants OWNER TO postgres;
ALTER VIEW public.master_shares OWNER TO postgres;
REVOKE ALL ON public.master_assistants FROM PUBLIC, anon;
REVOKE ALL ON public.master_shares FROM PUBLIC, anon;
GRANT SELECT ON public.master_assistants TO authenticated, service_role;
GRANT SELECT ON public.master_shares TO authenticated, service_role;

COMMENT ON VIEW public.master_assistants IS
  'One company (v2.2987): adoption BY RULE — every live dev/master paired with every live assistant, controller and estimator. Replaces the synced table so the 45 RPCs and 84 policies that still name master_assistants keep answering yes for the whole office with nothing to sync. Not an access decision: is_office_staff() is.';
COMMENT ON VIEW public.master_shares IS
  'One company (v2.2987): sharing BY RULE — every live dev/master paired with every other. Replaces the synced table; see master_assistants.';

-- 4) Re-bind the policies that name the pair -------------------------------------------------

-- ---- v2.2987: policies re-bound to the master_assistants / master_shares VIEWS ----
-- GENERATED by scripts/one-company-policy-sweep.py --rebind — 84 policies, bodies byte-identical to
-- their live definitions; DROP + CREATE only so the parsed expression points at the view (a policy
-- expression binds relations by OID, so a renamed table would otherwise still be read).

-- bids_submission_entries.Devs masters assistants estimators primaries can read bids subm  (from 20260906200000_one_company_policy_sweep.sql)
DROP POLICY IF EXISTS "Devs masters assistants estimators primaries can read bids subm" ON public."bids_submission_entries";
CREATE POLICY "Devs masters assistants estimators primaries can read bids subm" ON public."bids_submission_entries"
  FOR SELECT
  USING (public.is_office_staff() OR (EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role), CAST('assistant' AS public.user_role), CAST('estimator' AS public.user_role), CAST('primary' AS public.user_role)])) AND EXISTS (SELECT 1 FROM public.bids AS b WHERE b.id = bids_submission_entries.bid_id AND (b.created_by = (SELECT auth.uid() AS uid) OR EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('assistant' AS public.user_role), CAST('estimator' AS public.user_role), CAST('master_technician' AS public.user_role)])) OR (EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = CAST('primary' AS public.user_role)) AND (EXISTS (SELECT 1 FROM public.customers AS c INNER JOIN public.master_primaries AS mp ON mp.master_id = c.master_user_id WHERE c.id = b.customer_id AND mp.primary_id = (SELECT auth.uid() AS uid)) OR EXISTS (SELECT 1 FROM public.master_primaries AS mp WHERE mp.master_id = b.created_by AND mp.primary_id = (SELECT auth.uid() AS uid)) OR (b.gc_builder_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.bids_gc_builders AS bgb INNER JOIN public.master_primaries AS mp ON mp.master_id = bgb.created_by WHERE bgb.id = b.gc_builder_id AND mp.primary_id = (SELECT auth.uid() AS uid))) OR EXISTS (SELECT 1 FROM public.master_assistants AS ma INNER JOIN public.master_primaries AS mp ON mp.master_id = ma.master_id WHERE ma.assistant_id = b.created_by AND mp.primary_id = (SELECT auth.uid() AS uid))))))));

