  USING (public.is_office_staff() OR (EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role), CAST('assistant' AS public.user_role)])) AND (master_user_id = (SELECT auth.uid() AS uid) OR EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role)])) OR EXISTS (SELECT 1 FROM public.master_assistants WHERE master_assistants.master_id = projects.master_user_id AND master_assistants.assistant_id = (SELECT auth.uid() AS uid)))))
  WITH CHECK (public.is_office_staff() OR (EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role), CAST('assistant' AS public.user_role)])) AND (EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role)])) OR (master_user_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.master_assistants WHERE master_assistants.master_id = projects.master_user_id AND master_assistants.assistant_id = (SELECT auth.uid() AS uid)))) AND EXISTS (SELECT 1 FROM public.customers WHERE customers.id = projects.customer_id AND (customers.master_user_id = (SELECT auth.uid() AS uid) OR EXISTS (SELECT 1 FROM public.users WHERE users.id = (SELECT auth.uid() AS uid) AND users.role = ANY(ARRAY[CAST('dev' AS public.user_role), CAST('master_technician' AS public.user_role)])) OR EXISTS (SELECT 1 FROM public.master_assistants WHERE master_assistants.master_id = customers.master_user_id AND master_assistants.assistant_id = (SELECT auth.uid() AS uid))))));

